ADMIN_PASSWORD = os.environ.get('QUARK_ADMIN_PASSWORD', 'change-this-password')
DB_PATH = Path(__file__).with_name('quark.db')
FACTS = [
 {'tag':'Astronomy','title':'A Day Longer Than a Year','text':'Venus spins so slowly that one day on Venus (about 243 Earth days) is longer than its year (about 225 Earth days).'},
 {'tag':'Physics','title':'Light from the Past','text':'Sunlight takes about 8 minutes and 20 seconds to reach Earth, so you always see the Sun as it was over eight minutes ago.'},
 {'tag':'Biology','title':"Your Body's Microbes",'text':'Your body hosts roughly as many bacterial cells as human cells — around 38 trillion of them, mostly in your gut.'},
 {'tag':'Chemistry','title':'Honey Never Spoils','text':'Thanks to its low water content and acidity, honey resists bacterial growth. Edible honey has been found in ancient Egyptian tombs.'},
 {'tag':'Earth Science','title':'The Growing Himalayas','text':'The Indian plate is still pushing into Asia, so the Himalayas continue to rise by a few millimetres every year.'},
 {'tag':'Physics','title':'Mostly Empty Space','text':'An atom is almost entirely empty space. If its nucleus were a marble, the electrons would be found across an area the size of a stadium.'},
 {'tag':'Biology','title':'Octopus Hearts','text':'An octopus has three hearts and blue blood, which uses copper-based haemocyanin to carry oxygen.'},
 {'tag':'Astronomy','title':'Neutron Star Density','text':'A teaspoon of neutron-star material would have a mass of roughly a billion tonnes on Earth.'},
 {'tag':'Chemistry','title':'Diamonds and Pencils','text':'Diamond and graphite are both made of pure carbon — the difference is how their atoms are arranged.'},
 {'tag':'Biology','title':'DNA Unravelled','text':'If the DNA in just one of your cells were stretched out, it would measure about two metres long.'},
 {'tag':'Physics','title':'Water Expands When It Freezes','text':'Water becomes less dense as it freezes. That is why ice floats and lakes freeze from the top down.'},
 {'tag':'Mathematics','title':'The Birthday Paradox','text':'In a room of just 23 people, there is better than a 50% chance that two share a birthday.'},
]
QUIZ = [
 {'q':'Which planet is known as the Red Planet?','options':['Venus','Mars','Jupiter','Mercury'],'answer':1,'why':'Iron oxide (rust) in its soil gives Mars its reddish colour.'},
 {'q':'What is the chemical symbol for gold?','options':['Go','Gd','Au','Ag'],'answer':2,'why':'Au comes from the Latin word for gold, aurum.'},
 {'q':'Which part of the cell is called its powerhouse?','options':['Nucleus','Ribosome','Mitochondrion','Golgi body'],'answer':2,'why':'Mitochondria produce most of a cell’s energy in the form of ATP.'},
 {'q':'What is the approximate speed of light in a vacuum?','options':['300,000 km/s','30,000 km/s','3,000 km/s','3,000,000 km/s'],'answer':0,'why':'Light travels about 299,792 kilometres every second.'},
 {'q':'Which gas do plants absorb during photosynthesis?','options':['Oxygen','Nitrogen','Carbon dioxide','Hydrogen'],'answer':2,'why':'Plants take in carbon dioxide and release oxygen as a by-product.'},
 {'q':'Who proposed the three laws of motion?','options':['Albert Einstein','Isaac Newton','Galileo Galilei','C. V. Raman'],'answer':1,'why':'Newton published the laws in Principia Mathematica in 1687.'},
 {'q':'Which Indian scientist won the 1930 Nobel Prize in Physics?','options':['Homi Bhabha','S. N. Bose','C. V. Raman','J. C. Bose'],'answer':2,'why':'C. V. Raman was honoured for his work on the scattering of light.'},
 {'q':'What is the hardest naturally occurring mineral?','options':['Quartz','Diamond','Iron','Granite'],'answer':1,'why':'Diamond’s tightly bonded carbon lattice makes it exceptionally hard.'},
]
BRANCHES = [('⚛️','Physics'),('🧪','Chemistry'),('🧬','Biology'),('🔭','Astronomy'),('🤖','Robotics'),('🌿','Ecology'),('📐','Maths'),('🦠','Microbes'),('🌋','Geology')]
BOARD = [
 ('Teacher In-Charge','Mr. Abhinav Gaur Kaptaan'),('Editor-in-Chief','Dhruv Aggarwal'),
 ('Senior Editors','Pingalaksh Goyal · Aayansh Agarwal'),('Creative Editors','Tanay Singal · Yogit Parmar'),
 ('Editors','Ansh Gupta · Shivank Gupta')]
ARTICLE_TYPES = ['General Scientific Article','Experiment Log','Science Movie Review','Science Book Review','Scientific News Updates','Scientist Interview']

def db():
    con=sqlite3.connect(DB_PATH); con.row_factory=sqlite3.Row
    con.execute('''CREATE TABLE IF NOT EXISTS submissions (id INTEGER PRIMARY KEY, reference TEXT UNIQUE, name TEXT, grade TEXT, title TEXT, type TEXT, content TEXT, word_count INTEGER, status TEXT, submitted_at TEXT)''')
    con.execute('''CREATE TABLE IF NOT EXISTS quiz_attempts (id INTEGER PRIMARY KEY, score INTEGER, total INTEGER, pct REAL, created_at TEXT)''')
    existing={r[1] for r in con.execute('PRAGMA table_info(submissions)')}
    for col,decl in [('email','TEXT'),('abstract','TEXT'),('keywords','TEXT'),('updated_at','TEXT')]:
        if col not in existing: con.execute(f'ALTER TABLE submissions ADD COLUMN {col} {decl}')
    con.commit(); return con

def page():
    facts_json=json.dumps(FACTS, ensure_ascii=False).replace('</','<\\/')
    quiz_json=json.dumps(QUIZ, ensure_ascii=False).replace('</','<\\/')
    branches_json=json.dumps(BRANCHES, ensure_ascii=False)
    board_html=''.join(f'<article class="member"><span>{html.escape(role)}</span><h3>{html.escape(name)}</h3></article>' for role,name in BOARD)
    types=''.join(f'<option>{html.escape(t)}</option>' for t in ARTICLE_TYPES)
