def admin_page():
    return r'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Quark · Editorial Dashboard</title>
<style>
:root{--brown:#4a2c1a;--dark:#2e1a0e;--paper:#faf5ec;--gold:#c5a059;--muted:#725d49}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:#302116;font-family:Georgia,serif}.top{background:var(--dark);color:#fff;padding:24px max(22px,calc((100% - 1100px)/2));border-bottom:3px solid var(--gold)}.top a{color:#f3cb75}.wrap{max-width:1100px;margin:auto;padding:28px 20px}.login,.submission{background:white;border:1px solid #e5d8c2;border-top:3px solid var(--gold);padding:22px;border-radius:7px;margin:16px 0}.login input,.toolbar input,.toolbar select{padding:11px;border:1px solid #d9c6a3;border-radius:4px}.btn{background:var(--brown);color:white;border:0;padding:11px 16px;border-radius:4px;cursor:pointer}.btn.gold{background:var(--gold);color:var(--dark)}.muted{color:var(--muted)}.toolbar{display:flex;gap:10px;flex-wrap:wrap;margin:18px 0}.toolbar input{flex:1;min-width:180px}.submission h3{margin:4px 0 8px;color:var(--brown)}.meta{font:12px Arial;color:var(--muted);line-height:1.8}.pill{display:inline-block;background:#f3e9d6;padding:5px 9px;border-radius:20px;font:11px Arial;margin:4px 4px 4px 0}.content{white-space:pre-wrap;line-height:1.7;background:#faf5ec;padding:15px;border-radius:5px;margin-top:12px}.row{display:flex;justify-content:space-between;gap:12px;align-items:center;flex-wrap:wrap}.hidden{display:none}.error{color:#a32e21}.success{color:#27633a}
</style></head><body><header class="top"><h1>QUARK · Editorial Desk</h1><p>Private submission management for the Editorial Board</p><a href="/">← Back to Quark website</a></header><main class="wrap"><section class="login" id="login"><h2>Board sign-in</h2><p class="muted">Enter the editorial dashboard password provided by the website administrator.</p><input id="password" type="password" placeholder="Dashboard password"><button class="btn" id="login-btn">Sign in</button><p id="login-msg" class="error"></p></section><section id="desk" class="hidden"><div class="row"><div><h2>Article submissions</h2><p class="muted">Review, search and update article progress.</p></div><button class="btn" id="refresh">Refresh</button></div><div class="toolbar"><input id="search" placeholder="Search title, author or reference"><select id="status-filter"><option value="">All statuses</option><option>received</option><option>under review</option><option>revision requested</option><option>accepted</option><option>rejected</option><option>published</option></select></div><div id="items"></div></section></main>
<script>
let key='';const $=id=>document.getElementById(id);
$('login-btn').onclick=async()=>{key=$('password').value;try{let r=await fetch('/api/admin/submissions',{headers:{'X-Admin-Key':key}});if(!r.ok)throw Error('Incorrect password or dashboard is not configured.');$('login').classList.add('hidden');$('desk').classList.remove('hidden');render(await r.json())}catch(e){$('login-msg').textContent=e.message}};
$('refresh').onclick=load;async function load(){let r=await fetch('/api/admin/submissions',{headers:{'X-Admin-Key':key}});if(!r.ok){$('items').textContent='Could not load submissions.';return}render(await r.json())}
function render(rows){let q=$('search').value.toLowerCase(),st=$('status-filter').value;rows=rows.filter(x=>(!st||x.status===st)&&JSON.stringify(x).toLowerCase().includes(q));$('items').innerHTML=rows.length?rows.map(x=>`<article class="submission"><div class="row"><div><span class="pill">${x.status}</span><span class="pill">${x.type}</span><h3>${esc(x.title)}</h3><div class="meta">By ${esc(x.name)} · ${esc(x.grade||'Grade not provided')} · ${x.word_count} words<br>${esc(x.reference)} · ${new Date(x.submitted_at).toLocaleString()} · ${esc(x.email||'No email provided')}</div></div><select data-status="${x.reference}">${['received','under review','revision requested','accepted','rejected','published'].map(v=>`<option ${v===x.status?'selected':''}>${v}</option>`).join('')}</select></div><p>${esc(x.abstract||'No abstract provided')}</p><div class="meta">Keywords: ${esc(x.keywords||'—')}</div><details><summary>Read full article</summary><div class="content">${esc(x.content)}</div></details><div class="row" style="margin-top:12px"><span class="meta">Last updated: ${x.updated_at?new Date(x.updated_at).toLocaleString():'Not updated'}</span><button class="btn gold" data-save="${x.reference}">Save status</button></div></article>`).join(''):'<p class="muted">No matching submissions yet.</p>';$('items').querySelectorAll('[data-save]').forEach(b=>b.onclick=async()=>{let ref=b.dataset.save,sel=$('items').querySelector(`[data-status="${ref}"]`);let r=await fetch('/api/admin/submissions/'+ref,{method:'POST',headers:{'Content-Type':'application/json','X-Admin-Key':key},body:JSON.stringify({status:sel.value})});if(r.ok){b.textContent='Saved ✓';setTimeout(load,500)}else alert('Could not update status')})}
function esc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
$('search').oninput=load;$('status-filter').onchange=load;
</script></body></html>'''


def notify_board(reference, name, title, typ):
    host=os.environ.get('SMTP_HOST'); recipient=os.environ.get('BOARD_EMAIL')
    if not host or not recipient: return False
    import smtplib
    from email.message import EmailMessage
    msg=EmailMessage(); msg['Subject']=f'New Quark submission: {title}'; msg['From']=os.environ.get('SMTP_FROM',os.environ.get('SMTP_USER','quark@localhost')); msg['To']=recipient
    msg.set_content(f'A new article has been submitted to Quark.\\n\\nTitle: {title}\\nAuthor: {name}\\nType: {typ}\\nReference: {reference}\\n\\nOpen the Editorial Desk at /editor to review it.')
    with smtplib.SMTP(host,int(os.environ.get('SMTP_PORT','587')),timeout=10) as server:
        server.starttls()
        user=os.environ.get('SMTP_USER'); password=os.environ.get('SMTP_PASSWORD')
        if user and password: server.login(user,password)
        server.send_message(msg)
    return True


class Handler(BaseHTTPRequestHandler):
    def send_json(self, code, obj):
        data=json.dumps(obj,ensure_ascii=False).encode(); self.send_response(code); self.send_header('Content-Type','application/json; charset=utf-8'); self.send_header('Content-Length',str(len(data))); self.send_header('Access-Control-Allow-Origin','*'); self.end_headers(); self.wfile.write(data)
    def do_OPTIONS(self):
        self.send_response(204); self.send_header('Access-Control-Allow-Headers','Content-Type'); self.send_header('Access-Control-Allow-Methods','GET, POST, OPTIONS'); self.end_headers()
    def do_GET(self):
        path=urlparse(self.path).path
        if path=='/editor':
            data=admin_page().encode(); self.send_response(200); self.send_header('Content-Type','text/html; charset=utf-8'); self.send_header('Content-Length',str(len(data))); self.end_headers(); self.wfile.write(data); return
        if path=='/':
            data=page().encode(); self.send_response(200); self.send_header('Content-Type','text/html; charset=utf-8'); self.send_header('Content-Length',str(len(data))); self.end_headers(); self.wfile.write(data); return
        if path.startswith('/assets/'):
            asset_dir=Path(__file__).with_name('assets').resolve(); asset=(asset_dir / Path(path).name).resolve()
            if asset.parent==asset_dir and asset.is_file():
                data=asset.read_bytes(); self.send_response(200); self.send_header('Content-Type','image/png' if asset.suffix.lower()=='.png' else 'image/jpeg'); self.send_header('Content-Length',str(len(data))); self.end_headers(); self.wfile.write(data); return
        if path=='/api/admin/submissions':
            if not ADMIN_PASSWORD or self.headers.get('X-Admin-Key')!=ADMIN_PASSWORD: return self.send_json(401,{'detail':'Unauthorized'})
            with db() as con: rows=con.execute('SELECT reference,name,grade,email,title,type,abstract,keywords,content,word_count,status,submitted_at,updated_at FROM submissions ORDER BY submitted_at DESC').fetchall()
            return self.send_json(200,[dict(r) for r in rows])
        if path=='/api/facts': return self.send_json(200,FACTS)
        if path=='/api/quiz': return self.send_json(200,[{k:v for k,v in q.items() if k!='answer'} for q in QUIZ])
        if path.startswith('/api/submissions/'):
            ref=path.rsplit('/',1)[-1].upper()
            with db() as con: row=con.execute('SELECT reference,title,status,submitted_at FROM submissions WHERE reference=?',(ref,)).fetchone()
            if not row:return self.send_json(404,{'detail':'Submission not found'})
            return self.send_json(200,dict(row))
        if path=='/api/stats':
            with db() as con: counts={t:con.execute(f'SELECT COUNT(*) FROM {t}').fetchone()[0] for t in ('submissions','quiz_attempts')}
            return self.send_json(200,{'facts':len(FACTS),'quiz_questions':len(QUIZ),**counts})
        self.send_json(404,{'detail':'Not found'})
    def do_POST(self):
        path=urlparse(self.path).path
        try: payload=json.loads(self.rfile.read(int(self.headers.get('Content-Length',0))) or b'{}')
        except Exception:return self.send_json(400,{'detail':'Invalid JSON'})
        if path.startswith('/api/admin/submissions/'):
            if not ADMIN_PASSWORD or self.headers.get('X-Admin-Key')!=ADMIN_PASSWORD: return self.send_json(401,{'detail':'Unauthorized'})
            ref=path.rsplit('/',1)[-1].upper(); status=str(payload.get('status','')).strip().lower()
            allowed={'received','under review','revision requested','accepted','rejected','published'}
            if status not in allowed:return self.send_json(422,{'detail':'Invalid status'})
            now=datetime.datetime.now(datetime.timezone.utc).isoformat()
            with db() as con: cur=con.execute('UPDATE submissions SET status=?,updated_at=? WHERE reference=?',(status,now,ref))
            if cur.rowcount==0:return self.send_json(404,{'detail':'Submission not found'})
            return self.send_json(200,{'reference':ref,'status':status,'updated_at':now})
        if path=='/api/quiz/attempts':
            try: score=int(payload['score']); total=int(payload['total']); assert total>0 and 0<=score<=total
            except Exception:return self.send_json(422,{'detail':'Invalid quiz score'})
            pct=score/total
            with db() as con:
                before=con.execute('SELECT COUNT(*) FROM quiz_attempts').fetchone()[0]; lower=con.execute('SELECT COUNT(*) FROM quiz_attempts WHERE pct < ?',(pct,)).fetchone()[0]
                con.execute('INSERT INTO quiz_attempts(score,total,pct,created_at) VALUES(?,?,?,?)',(score,total,pct,datetime.datetime.now(datetime.timezone.utc).isoformat()))
                avg=con.execute('SELECT AVG(score) FROM quiz_attempts').fetchone()[0]
            return self.send_json(200,{'attempts':before+1,'average_score':round(avg or 0,1),'beat_percent':round(100*lower/before) if before else 100})
        if path=='/api/submissions':
            if payload.get('bot_field'):return self.send_json(400,{'detail':'Submission rejected'})
            name=str(payload.get('name','')).strip(); title=str(payload.get('title','')).strip(); content=str(payload.get('content','')).strip(); typ=str(payload.get('type','General Scientific Article')).strip()
            if not name or not title or len(content)<20:return self.send_json(422,{'detail':'Please provide your name, title and at least 20 characters of content.'})
            if typ not in ARTICLE_TYPES:typ=ARTICLE_TYPES[0]
            now=datetime.datetime.now(datetime.timezone.utc).isoformat(); ref=f"QRK-{datetime.datetime.now().year}-{secrets.token_hex(3).upper()}"
            email=str(payload.get('email','')).strip(); abstract=str(payload.get('abstract','')).strip(); keywords=str(payload.get('keywords','')).strip()
            with db() as con:con.execute('INSERT INTO submissions(reference,name,grade,title,type,content,word_count,status,submitted_at,email,abstract,keywords) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)',(ref,name,str(payload.get('grade','')).strip(),title,typ,content,len(content.split()),'received',now,email,abstract,keywords))
            email_sent=False
            try: email_sent=notify_board(ref,name,title,typ)
            except Exception as exc: print('Board email notification failed:',exc)
            return self.send_json(201,{'reference':ref,'name':name,'title':title,'type':typ,'status':'received','submitted_at':now,'word_count':len(content.split()),'board_email_sent':email_sent})
        self.send_json(404,{'detail':'Not found'})
    def log_message(self, fmt, *args): print('%s - %s'%(self.address_string(),fmt%args))

if __name__=='__main__':
    db().close()
    print(f'Quark is running at http://{HOST}:{PORT}  (Ctrl+C to stop)')
    try: ThreadingHTTPServer((HOST,PORT),Handler).serve_forever()
    except KeyboardInterrupt: print('\nQuark server stopped.')
